//! BF16 (bfloat16) storage type. Zig 0.16.0's standard library has no bf16 type.
//! Conversions match PyTorch: round to nearest with ties to even, and every NaN
//! becomes 0x7FC0. The reference vectors in vectors.zig were generated by PyTorch.

const std = @import("std");
const vectors = @import("vectors.zig");

/// One bfloat16 value, stored as its 16-bit pattern.
pub const bf16_t = struct {
    bits: u16,

    /// Rounds `value` to the nearest BF16, with ties going to the even mantissa.
    /// Every NaN becomes 0x7FC0. The sign and payload are dropped, as in PyTorch.
    pub fn from_f32(value: f32) bf16_t {
        const x: u32 = @bitCast(value);
        if (x & 0x7FFF_FFFF > 0x7F80_0000) return .{ .bits = 0x7FC0 };
        const rounding_bias: u32 = 0x7FFF + ((x >> 16) & 1);
        return .{ .bits = @intCast((x + rounding_bias) >> 16) };
    }

    /// Widens to F32 exactly. A BF16 is the top 16 bits of an F32.
    pub fn to_f32(self: bf16_t) f32 {
        return @bitCast(@as(u32, self.bits) << 16);
    }
};

/// Widens little-endian BF16 values from `src` into `dst`. `src.len` must be `2 * dst.len`.
pub fn widen_little_endian(dst: []f32, src: []const u8) void {
    std.debug.assert(src.len == 2 * dst.len);
    for (dst, 0..) |*out, i| {
        const bits = std.mem.readInt(u16, src[2 * i ..][0..2], .little);
        out.* = (bf16_t{ .bits = bits }).to_f32();
    }
}

test "bf16_t is two bytes" {
    try std.testing.expectEqual(@as(usize, 2), @sizeOf(bf16_t));
}

test "from_f32 matches PyTorch on every reference vector" {
    for (vectors.Pairs) |pair| {
        const input: f32 = @bitCast(pair[0]);
        try std.testing.expectEqual(@as(u16, @intCast(pair[1])), bf16_t.from_f32(input).bits);
    }
}

test "every bf16_t pattern survives a round trip through f32" {
    var bits: u32 = 0;
    while (bits <= 0xFFFF) : (bits += 1) {
        const value = (bf16_t{ .bits = @intCast(bits) }).to_f32();
        const back = bf16_t.from_f32(value).bits;
        const is_nan = (bits & 0x7FFF) > 0x7F80;
        const expected: u16 = if (is_nan) 0x7FC0 else @intCast(bits);
        try std.testing.expectEqual(expected, back);
    }
}

test "widen_little_endian reads little-endian values" {
    // 1.0 is 0x3F80 and -2.0 is 0xC000, stored little-endian.
    const bytes = [_]u8{ 0x80, 0x3F, 0x00, 0xC0 };
    var out: [2]f32 = undefined;
    widen_little_endian(&out, &bytes);
    try std.testing.expectEqual(@as(f32, 1.0), out[0]);
    try std.testing.expectEqual(@as(f32, -2.0), out[1]);
}
